DROP TABLE IF EXISTS `checklist_herramientas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `checklist_herramientas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `salida_checklist_id` int(11) NOT NULL,
  `herramienta` varchar(255) DEFAULT NULL,
  `disponible` tinyint(4) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_checklist_herramientas_salidas_checklists1_idx` (`salida_checklist_id`),
  CONSTRAINT `fk_checklist_herramientas_salidas_checklists1` FOREIGN KEY (`salida_checklist_id`) REFERENCES `salidas_checklists` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

