DROP TABLE IF EXISTS `vehiculos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vehiculos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `placa` varchar(255) DEFAULT NULL,
  `marca` varchar(255) DEFAULT NULL,
  `modelo` varchar(255) DEFAULT NULL,
  `anio` year(4) DEFAULT NULL,
  `estatus` enum('disponible','ocupado','inactivo','baja') DEFAULT NULL,
  `kilometraje_actual` int(11) DEFAULT NULL,
  `poliza_seguro_pdf` varchar(255) DEFAULT NULL,
  `poliza_seguro_vencimiento` date DEFAULT NULL,
  `tarjeta_circulacion_pdf` varchar(255) DEFAULT NULL,
  `tarjeta_circulacion_vencimiento` date DEFAULT NULL,
  `documentacion_estatus` enum('completa','vencida','incompleta') DEFAULT NULL,
  `foto_principal` varchar(255) DEFAULT NULL,
  `tenencia_vencimiento` date DEFAULT NULL,
  `tenencia_estatus` enum('vigente','proxima','vencida','sin_registro') NOT NULL DEFAULT 'sin_registro',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_vehiculos_tenencia_vencimiento` (`tenencia_vencimiento`),
  KEY `idx_vehiculos_tenencia_estatus` (`tenencia_estatus`),
  KEY `idx_vehiculos_estatus` (`estatus`),
  KEY `idx_vehiculos_documentacion_estatus` (`documentacion_estatus`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
